1	{
2	  "name": "quill-press",
3	  "version": "0.1.0",
4	  "private": true,
5	  "type": "module",
6	  "scripts": {
7	    "start": "node server.ts serve",
8	    "help": "node server.ts --help"
9	  }
10	}
11

1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
4	import { randomUUID } from 'node:crypto';
5	import { join } from 'node:path';
6	
7	const PRODUCT: string = 'QuillPress';
8	const RESOURCE: string = 'articles';
9	const MAX_BODY_BYTES: number = 5 * 1024 * 1024;
10	const PAGE: string = `<!doctype html>
11	<html lang="zh-CN">
12	<meta charset="utf-8">
13	<meta name="viewport" content="width=device-width,initial-scale=1">
14	<title>QuillPress · 内容编辑与刊物发布</title>
15	<style>
16	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1f2328}
17	a{color:#175b9c}
18	h2{margin-top:2rem}
19	form{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0 1.5rem}
20	form.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
21	label{display:block;font-weight:600;margin:.9rem 0 .3rem}
22	input[type=text],textarea{width:100%;box-sizing:border-box;font:inherit;padding:.5rem .6rem;border:1px solid #d0d7de;border-radius:6px;background:#fff;color:inherit}
23	textarea{resize:vertical}
24	button{margin-top:1.1rem;font:inherit;padding:.5rem 1.3rem;border-radius:6px;border:1px solid #175b9c;background:#175b9c;color:#fff;cursor:pointer}
25	button.secondary{background:#fff;color:#175b9c;margin-left:.6rem}
26	button:disabled{opacity:.55;cursor:default}
27	button.danger{border-color:#c0392b;background:#fff;color:#c0392b}
28	.status{margin:.8rem 0 0;min-height:1.4em}
29	.status.ok{color:#1a7f37}.status.err{color:#c0392b}.status.warn{color:#8a5a00}
30	.edit-banner{margin:0 0 .25rem;padding:.6rem .8rem;border-radius:6px;background:#eef4fb;border:1px solid #b6d2ee;color:#14467a;font-size:.92rem}
31	.edit-banner code{background:#dde9f6;padding:0 .3rem;border-radius:3px}
32	.edit-banner .meta{color:#3d6391;font-size:.85rem;margin-top:.2rem}
33	ul.articles{list-style:none;padding:0;margin:0}
34	article.draft{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0}
35	article.draft.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
36	.draft h3{margin:0 0 .4rem;word-break:break-word}
37	.draft .meta{color:#656d76;font-size:.85rem;margin:0 0 .5rem}
38	.draft .summary{white-space:pre-wrap;word-break:break-word;margin:0 0 .4rem;color:#3a4149}
39	.draft .actions{margin:.6rem 0 0}
40	.draft .actions button{margin:0;padding:.3rem .9rem;font-size:.88rem}
41	.draft .editing-tag{margin-left:.5rem;font-size:.78rem;font-weight:600;color:#175b9c;border:1px solid #175b9c;border-radius:999px;padding:0 .55rem;vertical-align:middle}
42	.empty{color:#656d76}
43	.empty.err{color:#c0392b}
44	.conflict{margin-top:1rem;border:1px solid #d9a441;border-radius:8px;background:#fffaf0;padding:1rem 1.25rem}
45	.conflict h3{margin:0 0 .3rem;color:#8a5a00;font-size:1.05rem}
46	.conflict .conflict-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:.7rem}
47	@media (max-width:46rem){.conflict .conflict-grid{grid-template-columns:1fr}}
48	.conflict .ver{border:1px solid #d0d7de;border-radius:6px;padding:.7rem .85rem;background:#fff;min-width:0}
49	.conflict .ver.saved{border-color:#8ab46a;background:#f6fbf2}
50	.conflict .ver h4{margin:0 0 .5rem;font-size:.92rem}
51	.conflict .ver dl{margin:0}
52	.conflict .ver dt{font-weight:600;font-size:.82rem;color:#57606a;margin-top:.5rem}
53	.conflict .ver dt:first-child{margin-top:0}
54	.conflict .ver dd{margin:.15rem 0 0;white-space:pre-wrap;word-break:break-word;font-size:.88rem;background:#f6f8fa;border-radius:4px;padding:.35rem .5rem;max-height:12rem;overflow:auto}
55	.conflict .ver.saved dd{background:#eef5e8}
56	.conflict .ver dd.empty-field{color:#8a8f98;font-style:italic;background:transparent;padding:0}
57	.conflict .actions{margin-top:.8rem}
58	.conflict .actions button{margin-top:0}
59	.conflict .actions .tip{font-size:.82rem;color:#8a5a00;margin-left:.6rem}
60	</style>
61	<main>
62	<h1>QuillPress</h1>
63	<p>内容编辑与刊物发布</p>
64	
65	<section aria-labelledby="compose-heading">
66	<h2 id="compose-heading">保存草稿</h2>
67	<form id="draft-form" autocomplete="off">
68	  <div id="edit-banner" class="edit-banner" hidden></div>
69	  <label for="title">标题</label>
70	  <input id="title" name="title" type="text">
71	  <label for="summary">摘要（可选）</label>
72	  <textarea id="summary" name="summary" rows="3"></textarea>
73	  <label for="body">正文</label>
74	  <textarea id="body" name="body" rows="10"></textarea>
75	  <button id="save-btn" type="submit">保存草稿</button>
76	  <button id="cancel-btn" class="secondary" type="button" hidden>取消编辑</button>
77	  <p id="status" class="status" role="status" aria-live="polite"></p>
78	  <div id="conflict-box" class="conflict" hidden></div>
79	</form>
80	</section>
81	
82	<section aria-labelledby="list-heading">
83	<h2 id="list-heading">草稿列表</h2>
84	<ul id="article-list" class="articles"></ul>
85	<p id="empty-tip" class="empty">草稿加载中…</p>
86	</section>
87	
88	<p><a href="/api/articles">查看文章列表接口</a> · <a href="/health">服务状态</a></p>
89	</main>
90	<script>
91	(function () {
92	  'use strict';
93	  var form = document.getElementById('draft-form');
94	  var titleInput = document.getElementById('title');
95	  var summaryInput = document.getElementById('summary');
96	  var bodyInput = document.getElementById('body');
97	  var saveBtn = document.getElementById('save-btn');
98	  var cancelBtn = document.getElementById('cancel-btn');
99	  var statusEl = document.getElementById('status');
100	  var editBanner = document.getElementById('edit-banner');
101	  var conflictBox = document.getElementById('conflict-box');
102	  var listEl = document.getElementById('article-list');
103	  var emptyTip = document.getElementById('empty-tip');
104	  var articles = [];
105	  var saving = false;
106	  // null = 新建草稿模式；对象 = 正在编辑的服务端版本 {id,title,summary,body,version}
107	  var editing = null;
108	  // 冲突对照区当前的操作按钮，读取最新内容期间需暂时禁用
109	  var conflictActionButtons = [];
110	
111	  function setStatus(text, kind) {
112	    statusEl.textContent = text || '';
113	    statusEl.className = 'status' + (kind ? ' ' + kind : '');
114	  }
115	  function setEmpty(text, kind) {
116	    emptyTip.textContent = text || '';
117	    emptyTip.className = 'empty' + (kind ? ' ' + kind : '');
118	    emptyTip.hidden = !text;
119	  }
120	  function hideConflict() {
121	    conflictBox.hidden = true;
122	    conflictBox.textContent = '';
123	    conflictActionButtons = [];
124	  }
125	  function setConflictActionsDisabled(disabled) {
126	    conflictActionButtons.forEach(function (btn) { btn.disabled = disabled; });
127	  }
128	  function formatTime(iso) {
129	    var d = new Date(iso);
130	    return isNaN(d.getTime()) ? String(iso) : d.toLocaleString();
131	  }
132	  function render() {
133	    var sorted = articles.slice().sort(function (a, b) {
134	      var ta = a && a.createdAt ? String(a.createdAt) : '';
135	      var tb = b && b.createdAt ? String(b.createdAt) : '';
136	      if (ta !== tb) return ta < tb ? 1 : -1;
137	      return 0;
138	    });
139	    listEl.textContent = '';
140	    sorted.forEach(function (article) {
141	      var isEditing = editing && editing.id === article.id;
142	      var card = document.createElement('article');
143	      card.className = 'draft' + (isEditing ? ' editing' : '');
144	      var h = document.createElement('h3');
145	      h.textContent = article.title == null ? '' : String(article.title);
146	      if (isEditing) {
147	        var tag = document.createElement('span');
148	        tag.className = 'editing-tag';
149	        tag.textContent = '编辑中';
150	        h.appendChild(tag);
151	      }
152	      var meta = document.createElement('p');
153	      meta.className = 'meta';
154	      meta.textContent = '创建时间：' + formatTime(article.createdAt);
155	      var summary = document.createElement('p');
156	      summary.className = 'summary';
157	      var summaryText = article.summary == null ? '' : String(article.summary);
158	      summary.textContent = summaryText;
159	      card.appendChild(h);
160	      card.appendChild(meta);
161	      if (summaryText) card.appendChild(summary);
162	      var actions = document.createElement('p');
163	      actions.className = 'actions';
164	      var editBtn = document.createElement('button');
165	      editBtn.type = 'button';
166	      editBtn.className = 'secondary';
167	      editBtn.textContent = isEditing ? '正在编辑' : '编辑';
168	      editBtn.disabled = !!isEditing;
169	      editBtn.addEventListener('click', function () { startEdit(article.id); });
170	      actions.appendChild(editBtn);
171	      card.appendChild(actions);
172	      var li = document.createElement('li');
173	      li.appendChild(card);
174	      listEl.appendChild(li);
175	    });
176	    setEmpty(sorted.length === 0 ? '还没有保存的草稿。' : '');
177	  }
178	  function load() {
179	    return fetch('/api/articles', { headers: { accept: 'application/json' } })
180	      .then(function (r) {
181	        if (!r.ok) throw new Error('HTTP ' + r.status);
182	        return r.json();
183	      })
184	      .then(function (data) {
185	        articles = data && Array.isArray(data.articles) ? data.articles : [];
186	        render();
187	      })
188	      .catch(function (err) {
189	        articles = [];
190	        listEl.textContent = '';
191	        setEmpty('草稿列表加载失败：' + (err && err.message ? err.message : err), 'err');
192	      });
193	  }
194	
195	  function setSaving(on, label) {
196	    saving = on;
197	    saveBtn.disabled = on;
198	    saveBtn.textContent = label || (editing ? '保存修改' : '保存草稿');
199	    cancelBtn.disabled = on;
200	  }
201	
202	  function enterCreateMode(message, kind) {
203	    editing = null;
204	    form.reset();
205	    form.classList.remove('editing');
206	    editBanner.hidden = true;
207	    editBanner.textContent = '';
208	    hideConflict();
209	    cancelBtn.hidden = true;
210	    saveBtn.textContent = '保存草稿';
211	    setStatus(message || '', kind || '');
212	    render();
213	  }
214	
215	  function renderEditBanner(article) {
216	    editBanner.textContent = '';
217	    var line1 = document.createElement('div');
218	    line1.textContent = '正在编辑草稿：';
219	    var code = document.createElement('code');
220	    code.textContent = String(article.title);
221	    line1.appendChild(code);
222	    var line2 = document.createElement('div');
223	    line2.className = 'meta';
224	    line2.textContent = '创建时间：' + formatTime(article.createdAt) + ' · 标识：' + String(article.id);
225	    editBanner.appendChild(line1);
226	    editBanner.appendChild(line2);
227	  }
228	
229	  function applyEditingState(article) {
230	    editing = {
231	      id: article.id,
232	      title: article.title,
233	      summary: article.summary,
234	      body: article.body,
235	      version: article.version
236	    };
237	    // 列表同步为本次载入的已保存内容，使该草稿的标题、摘要与“编辑中”标识
238	    // 与载入结果一致（载入的可能比列表缓存更新）。
239	    var idx = -1;
240	    for (var i = 0; i < articles.length; i++) {
241	      if (articles[i] && articles[i].id === article.id) { idx = i; break; }
242	    }
243	    if (idx >= 0) articles[idx] = article; else articles.push(article);
244	    titleInput.value = article.title == null ? '' : String(article.title);
245	    summaryInput.value = article.summary == null ? '' : String(article.summary);
246	    bodyInput.value = article.body == null ? '' : String(article.body);
247	    form.classList.add('editing');
248	    renderEditBanner(article);
249	    editBanner.hidden = false;
250	    cancelBtn.hidden = false;
251	    saveBtn.textContent = '保存修改';
252	    hideConflict();
253	    setStatus('已载入该草稿当前保存的内容，可以开始修改。', null);
254	    render();
255	    titleInput.focus();
256	  }
257	
258	  function isDirty() {
259	    if (!editing) {
260	      return titleInput.value !== '' || summaryInput.value !== '' || bodyInput.value !== '';
261	    }
262	    return titleInput.value !== editing.title
263	      || summaryInput.value !== editing.summary
264	      || bodyInput.value !== editing.body;
265	  }
266	
267	  function formSnapshot() {
268	    return {
269	      title: titleInput.value,
270	      summary: summaryInput.value,
271	      body: bodyInput.value
272	    };
273	  }
274	
275	  // 通过单篇接口读取草稿当前已保存的完整内容（含正文与 version），
276	  // 绝不使用列表里的摘要充当正文。
277	  function fetchArticle(id) {
278	    return fetch('/api/articles/' + encodeURIComponent(id), { headers: { accept: 'application/json' } })
279	      .then(function (r) {
280	        return r.json().catch(function () { return null; }).then(function (data) {
281	          if (!r.ok || !data || !data.article) {
282	            throw new Error(data && data.error ? data.error : ('HTTP ' + r.status));
283	          }
284	          return data.article;
285	        });
286	      });
287	  }
288	
289	  // 读取成功后按开始读取时的快照决定载入方式：三个字段均未变（含改动后
290	  // 又恢复原值）直接载入；任一字段不同则先说明载入将丢弃等待期间的新修改，
291	  // 由用户明确选择。选择保留时全部输入、原编辑对象与原版本基准都保持原状，
292	  // 当前输入也不会被当作目标文章的修改。
293	  function loadFetchedArticle(snapshot, article, confirmMessage, keepMessage) {
294	    if (titleInput.value === snapshot.title
295	      && summaryInput.value === snapshot.summary
296	      && bodyInput.value === snapshot.body) {
297	      applyEditingState(article);
298	      return;
299	    }
300	    if (window.confirm(confirmMessage)) {
301	      applyEditingState(article);
302	    } else {
303	      setStatus(keepMessage, null);
304	    }
305	  }
306	
307	  function startEdit(id) {
308	    if (saving) return;
309	    if (isDirty() && !window.confirm('当前表单有未保存的修改，打开另一篇草稿将放弃这些输入。确定继续吗？')) {
310	      return;
311	    }
312	    // 记录开始读取时的表单快照。读取期间表单仍可继续输入，
313	    // 成功返回时据此判断是否有等待期间的新修改需要用户明确取舍。
314	    var snapshot = formSnapshot();
315	    setSaving(true, '读取中…');
316	    setStatus('正在读取草稿内容…', null);
317	    fetchArticle(id)
318	      .then(function (article) {
319	        setSaving(false);
320	        loadFetchedArticle(snapshot, article,
321	          '目标草稿已读取完成，但等待期间你又修改了标题、摘要或正文。'
322	          + '打开目标草稿将放弃这些新修改。\\n\\n'
323	          + '点击“确定”放弃新修改并打开目标草稿；点击“取消”保留当前输入，继续原来的操作。',
324	          '已保留当前输入，未打开目标草稿。');
325	      })
326	      .catch(function (err) {
327	        setSaving(false);
328	        saveBtn.textContent = editing ? '保存修改' : '保存草稿';
329	        setStatus('打开草稿失败：' + (err && err.message ? err.message : err) + '，可稍后重试。', 'err');
330	      });
331	  }
332	
333	  // 冲突后点击“放弃当前输入并载入最新内容”：绝不能直接使用冲突响应里
334	  // 带回的内容——那之后其他页面可能又保存过，旧对照已过时。始终重新通过
335	  // 单篇接口读取发生冲突的同一篇草稿在本次读取时实际保存的版本，读取成功
336	  // 后才以其进入编辑状态。该操作只读取，不保存、删除或新建任何记录。
337	  function reloadLatestSaved() {
338	    if (saving || !editing) return;
339	    var id = editing.id;
340	    // 不提前清空表单：读取期间标题、摘要和正文仍可继续输入。
341	    var snapshot = formSnapshot();
342	    setSaving(true, '读取中…');
343	    setStatus('正在读取该草稿最新已保存的内容…', null);
344	    setConflictActionsDisabled(true);
345	    fetchArticle(id)
346	      .then(function (article) {
347	        setSaving(false);
348	        setConflictActionsDisabled(false);
349	        loadFetchedArticle(snapshot, article,
350	          '最新内容已读取完成，但等待期间你又修改了标题、摘要或正文。'
351	          + '载入最新内容将放弃这些新修改。\\n\\n'
352	          + '点击“确定”放弃新修改并载入最新内容；点击“取消”保留当前输入。',
353	          '已保留当前输入，未载入最新内容。');
354	      })
355	      .catch(function (err) {
356	        // 草稿已不存在或读取失败：保留全部当前输入与原编辑状态，
357	        // 恢复可操作状态，不显示载入成功、不退回新建模式。
358	        setSaving(false);
359	        saveBtn.textContent = editing ? '保存修改' : '保存草稿';
360	        setConflictActionsDisabled(false);
361	        setStatus('载入最新内容失败：' + (err && err.message ? err.message : err)
362	          + '，当前输入与编辑状态已保留，可稍后重试。', 'err');
363	      });
364	  }
365	
366	  cancelBtn.addEventListener('click', function () {
367	    if (saving || !editing) return;
368	    // 取消不提交任何修改，也不删除原文章，直接回到新建草稿状态
369	    if (isDirty() && !window.confirm('取消将放弃当前未保存的修改，原草稿不会被删除。确定取消编辑吗？')) {
370	      return;
371	    }
372	    enterCreateMode('已取消编辑，原草稿未改动。可以新建草稿。', null);
373	  });
374	
375	  function fieldValue(text, isEmpty) {
376	    var dd = document.createElement('dd');
377	    if (isEmpty) {
378	      dd.className = 'empty-field';
379	      dd.textContent = '（空）';
380	    } else {
381	      dd.textContent = text;
382	    }
383	    return dd;
384	  }
385	
386	  function showConflict(saved) {
387	    // 只展示对照，绝不重置表单、绝不自动重试覆盖
388	    conflictBox.textContent = '';
389	    var h = document.createElement('h3');
390	    h.textContent = '检测到较新的已保存内容';
391	    var p = document.createElement('p');
392	    p.textContent = '这篇草稿在其他页面已被修改并保存。为避免覆盖新版本，本次保存已被拒绝。你输入的内容仍保留在上方表单中，可对照右侧最新版本；只有明确放弃当前输入后，才会载入最新内容继续编辑。';
393	    conflictBox.appendChild(h);
394	    conflictBox.appendChild(p);
395	
396	    var grid = document.createElement('div');
397	    grid.className = 'conflict-grid';
398	
399	    var mine = document.createElement('div');
400	    mine.className = 'ver mine';
401	    var mineTitle = document.createElement('h4');
402	    mineTitle.textContent = '你正在编辑的内容（未保存）';
403	    mine.appendChild(mineTitle);
404	    var dl1 = document.createElement('dl');
405	    [['标题', titleInput.value, titleInput.value.trim() === ''],
406	     ['摘要', summaryInput.value, summaryInput.value === ''],
407	     ['正文', bodyInput.value, bodyInput.value === '']].forEach(function (pair) {
408	      var dt = document.createElement('dt');
409	      dt.textContent = pair[0];
410	      dl1.appendChild(dt);
411	      dl1.appendChild(fieldValue(pair[1], pair[2]));
412	    });
413	    mine.appendChild(dl1);
414	
415	    var theirs = document.createElement('div');
416	    theirs.className = 'ver saved';
417	    var tTitle = document.createElement('h4');
418	    tTitle.textContent = '最新已保存内容';
419	    theirs.appendChild(tTitle);
420	    var dl2 = document.createElement('dl');
421	    [['标题', saved.title, saved.title === ''],
422	     ['摘要', saved.summary, saved.summary === ''],
423	     ['正文', saved.body, saved.body === '']].forEach(function (pair) {
424	      var dt = document.createElement('dt');
425	      dt.textContent = pair[0];
426	      dl2.appendChild(dt);
427	      dl2.appendChild(fieldValue(pair[1], pair[2]));
428	    });
429	    theirs.appendChild(dl2);
430	
431	    grid.appendChild(mine);
432	    grid.appendChild(theirs);
433	    conflictBox.appendChild(grid);
434	
